/// <summary>
/// Defines Telemetry event names logged into AppInsights
/// </summary>
public final class ISMTelemetryEventNames
{
    public static const str MyEventName                         = 'MyEventName';
    public static const str BatchJobStatusUpdate                = 'BatchJobStatusUpdate';
    public static const str BatchJobCreated                     = 'BatchJobCreated';
    public static const str BatchStatusUpdate                   = 'BatchStatusUpdate';
    public static const str DMFDefinitionGroupExecutionHistory  = 'DMFExceutionHistory';
    public static const str DMFExportPackage                    = 'DMFExportPackage';
    public static const str DMFExportFile                       = 'DMFExportFile';
    public static const str DMFImport                           = 'DMFImport';
    public static const str DMFStagingLogMessage                = 'DMFStagingLogMessage';
    public static const str ExcelExportEnded                    = 'ExcelExportEnded';
    public static const str ExcelExportStarted                  = 'ExcelExportStarted';
    public static const str ExcelExportProgress                 = 'ExcelExportProgress';
    public static const str SQLStatement                        = 'SQLStatement';





}
